+ {id:'slime1',type:'enemy',name:'Meadow slime',x:26,y:18,hp:12,maxHp:12,level:1,damage:2},{id:'slime2',type:'enemy',name:'Mossback slime',x:31,y:25,hp:18,maxHp:18,level:2,damage:3},{id:'slime3',type:'enemy',name:'Meadow slime',x:12,y:9,hp:12,maxHp:12,level:1,damage:2},
+ {id:'herb1',type:'herb',name:'Sunleaf herb',x:17,y:11,amount:1},{id:'herb2',type:'herb',name:'Sunleaf herb',x:37,y:14,amount:1},{id:'herb3',type:'herb',name:'Sunleaf herb',x:24,y:27,amount:1},
