+let state={x:19,y:19,hp:30,maxHp:30,xp:0,coins:12,items:{wood:0,ore:0,herb:0,potion:1,blade:0},levels:{combat:1,forage:1,mining:1,craft:1},skillXp:{combat:0,forage:0,mining:0,craft:0},quest:{wood:false,ore:false,talked:false,done:false},equipped:false,day:1,minute:480};
+function load(){try{const saved=JSON.parse(localStorage.getItem('everdawn-save'));if(saved){state={...state,...saved,items:{...state.items,...saved.items},levels:{...state.levels,...saved.levels},skillXp:{...state.skillXp,...saved.skillXp},quest:{...state.quest,...saved.quest}};}}catch(e){}}
+function save(){try{localStorage.setItem('everdawn-save',JSON.stringify(state))}catch(e){}}
+load();
+function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);mapCanvas.width=260;mapCanvas.height=200;draw()};new ResizeObserver(resize).observe(canvas);
+const screen=(x,y)=>({x:x*TW-camera.x,y:y*TH-camera.y});
+function worldAt(px,py){return{x:(px+camera.x)/TW,y:(py+camera.y)/TH}}
+function message(text){const node=document.createElement('div');node.className='toast';node.textContent=text;document.querySelector('#feed').appendChild(node);setTimeout(()=>node.remove(),4100)}
+function find(id){return entities.find(e=>e.id===id)}function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
