+ for(const [key,label] of [['combat','combat'],['forage','forage'],['mining','mining'],['craft','craft']]){document.querySelector(`#${label}Lv`).textContent=state.levels[key];document.querySelector(`#${label}Xp`).style.width=`${100*state.skillXp[key]/(state.levels[key]*40)}%`}
