+ document.querySelector('#clock').textContent=`${state.minute<1080?'☀':'☾'} Day ${state.day} · ${String(Math.floor(state.minute/60)%24).padStart(2,'0')}:${String(state.minute%60).padStart(2,'0')}`;document.querySelector('#coords').textContent=`MEADOW · ${Math.floor(state.x)}, ${Math.floor(state.y)}`;
