function draw(){if(!W||!H)return;ctx.clearRect(0,0,W,H);const maxX=WW*TW-W,maxY=WH*TH-H;camera.x=Math.max(0,Math.min(maxX,state.x*TW-W/2));camera.y=Math.max(0,Math.min(maxY,state.y*TH-H/2));
 const x0=Math.max(0,Math.floor(camera.x/TW)-1),x1=Math.min(WW,Math.ceil((camera.x+W)/TW)+1),y0=Math.max(0,Math.floor(camera.y/TH)-1),y1=Math.min(WH,Math.ceil((camera.y+H)/TH)+1);
 for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){let p=screen(x,y),t=terrain(x,y),v=rand(x+81,y-41);let colors=t==='path'?['#968461','#8b7959','#a08d67']:t==='water'?['#467c78','#3c716e','#50857c']:t==='flower'?['#647c4f','#62794d','#6d8353']:t==='fern'?['#526f48','#58754c','#607a4d']:['#58774f','#5b7952','#5e7d54'];ctx.fillStyle=colors[Math.floor(v*colors.length)];ctx.fillRect(p.x,p.y,TW+1,TH+1);
 if(t==='water'){ctx.fillStyle='#9ac5b554';ctx.fillRect(p.x+8+v*15,p.y+9,TW*.35,1);ctx.fillRect(p.x+3,p.y+27,TW*.25,1)}else if(t==='path'){ctx.fillStyle='#b9a67b27';ctx.fillRect(p.x+4,p.y+6,TW*.28,2);ctx.fillRect(p.x+26,p.y+25,7,2)}else if(t==='flower'){ctx.fillStyle=v>.93?'#f0cf75':'#e6b5b0';ctx.beginPath();ctx.arc(p.x+9+v*26,p.y+8+rand(y,x)*22,1.8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d5cc8d';ctx.fillRect(p.x+17,p.y+25,2,2)}else{ctx.fillStyle='#b5c18b20';ctx.fillRect(p.x+8+v*26,p.y+8+rand(y,x)*22,2,1);if(v>.4){ctx.fillStyle='#283e3438';ctx.fillRect(p.x+Math.floor(v*34),p.y+31,5,1)}}
 }
 // soft pools of light, trees/objects ordered behind actor
 const visible=entities.filter(e=>e.amount!==0&&!(e.type==='enemy'&&e.hp<=0)).sort((a,b)=>a.y-b.y);for(const e of visible){if(e.type==='npc'||e.type==='camp'||e.type==='sign')continue;drawEntity(e)}
 for(const e of entities.filter(e=>['npc','camp','sign'].includes(e.type)))drawEntity(e);
 if(selected&&selected.amount!==0){const p=screen(selected.x,selected.y);ctx.strokeStyle='#f0ce84';ctx.lineWidth=2;ctx.setLineDash([4,3]);ctx.beginPath();ctx.ellipse(p.x+TW/2,p.y+TH/2,TW*.47,TH*.42,0,0,Math.PI*2);ctx.stroke();ctx.setLineDash([])}
 drawPlayer();drawMini();
}
function drawEntity(e){const p=screen(e.x,e.y),cx=p.x+TW/2,cy=p.y+TH/2,hidden=(cx<-40||cx>W+40||cy<-50||cy>H+60);if(hidden)return;ctx.save();
 if(e.type==='tree'){ctx.fillStyle='#263a2d77';ctx.beginPath();ctx.ellipse(cx,cy+12,21,9,0,0,7);ctx.fill();ctx.fillStyle='#674a32';ctx.fillRect(cx-4,cy-5,8,24);ctx.fillStyle='#365b3d';ctx.beginPath();ctx.arc(cx,cy-11,19,0,7);ctx.fill();ctx.fillStyle='#477349';ctx.beginPath();ctx.arc(cx-9,cy-18,13,0,7);ctx.arc(cx+8,cy-20,14,0,7);ctx.fill();ctx.fillStyle='#71905a';ctx.beginPath();ctx.arc(cx-8,cy-22,5,0,7);ctx.arc(cx+7,cy-25,5,0,7);ctx.fill();if(e.amount<3)ctx.globalAlpha=.68;
 }else if(e.type==='ore'){ctx.fillStyle='#28362e99';ctx.beginPath();ctx.ellipse(cx,cy+7,16,6,0,0,7);ctx.fill();ctx.fillStyle='#748783';ctx.beginPath();ctx.moveTo(cx-13,cy+7);ctx.lineTo(cx-9,cy-5);ctx.lineTo(cx-2,cy-14);ctx.lineTo(cx+8,cy-10);ctx.lineTo(cx+14,cy+4);ctx.lineTo(cx+9,cy+9);ctx.closePath();ctx.fill();ctx.fillStyle='#bc8b5a';ctx.beginPath();ctx.moveTo(cx-7,cy-3);ctx.lineTo(cx-2,cy-12);ctx.lineTo(cx+2,cy-8);ctx.lineTo(cx-1,cy+2);ctx.fill();ctx.fillStyle='#d6ab76';ctx.fillRect(cx+5,cy-3,3,7);
 }else if(e.type==='enemy'){const wobble=Math.sin(time*4+e.x)*2;ctx.fillStyle='#1f2c2999';ctx.beginPath();ctx.ellipse(cx,cy+7,14,6,0,0,7);ctx.fill();ctx.fillStyle=e.level>1?'#588c70':'#70a878';ctx.beginPath();ctx.ellipse(cx,cy-2+wobble,14,12,0,0,7);ctx.fill();ctx.fillStyle='#a1cc89';ctx.beginPath();ctx.ellipse(cx-5,cy-8+wobble,5,3,-.4,0,7);ctx.fill();ctx.fillStyle='#f4edcf';ctx.beginPath();ctx.arc(cx-4,cy-2+wobble,2,0,7);ctx.arc(cx+4,cy-2+wobble,2,0,7);ctx.fill();ctx.fillStyle='#28332e';ctx.fillRect(cx-4,cy-2+wobble,1,2);ctx.fillRect(cx+4,cy-2+wobble,1,2);if(e.hp<e.maxHp){ctx.fillStyle='#12201b';ctx.fillRect(cx-13,cy-20,26,3);ctx.fillStyle='#dc735c';ctx.fillRect(cx-13,cy-20,26*e.hp/e.maxHp,3)}
 }else if(e.type==='herb'){ctx.fillStyle='#28523d';for(let i=0;i<4;i++){ctx.save();ctx.translate(cx,cy+5);ctx.rotate(i*.85-.9);ctx.beginPath();ctx.ellipse(0,-7,3,9,0,0,7);ctx.fill();ctx.restore()}ctx.fillStyle='#f2cf79';ctx.beginPath();ctx.arc(cx,cy-10,3,0,7);ctx.fill()
 }else if(e.type==='npc'){ctx.fillStyle='#263c3077';ctx.beginPath();ctx.ellipse(cx,cy+9,12,5,0,0,7);ctx.fill();ctx.fillStyle='#d4b679';ctx.beginPath();ctx.arc(cx,cy-7,7,0,7);ctx.fill();ctx.fillStyle='#467261';ctx.fillRect(cx-9,cy,18,16);ctx.fillStyle='#e7d6ab';ctx.fillRect(cx-8,cy+12,6,8);ctx.fillRect(cx+2,cy+12,6,8);ctx.fillStyle='#dec77c';ctx.fillRect(cx-8,cy-9,16,4);ctx.fillStyle='#283a31';ctx.fillRect(cx-2,cy-8,1,2);ctx.fillRect(cx+3,cy-8,1,2)
 }else if(e.type==='camp'){ctx.fillStyle='#24342b99';ctx.beginPath();ctx.ellipse(cx,cy+7,14,5,0,0,7);ctx.fill();ctx.fillStyle='#6b5034';ctx.beginPath();ctx.moveTo(cx-10,cy+7);ctx.lineTo(cx+7,cy-2);ctx.lineTo(cx+10,cy+2);ctx.lineTo(cx-7,cy+10);ctx.fill();ctx.beginPath();ctx.moveTo(cx-9,cy);ctx.lineTo(cx+9,cy+7);ctx.lineTo(cx+7,cy+10);ctx.lineTo(cx-11,cy+3);ctx.fill();ctx.fillStyle='#ed9957';ctx.beginPath();ctx.moveTo(cx,cy+2);ctx.quadraticCurveTo(cx-8,cy-9,cx,cy-17);ctx.quadraticCurveTo(cx+9,cy-8,cx,cy+2);ctx.fill();ctx.fillStyle='#ffdc8c';ctx.beginPath();ctx.ellipse(cx,cy-4,3,6,0,0,7);ctx.fill()
 }else if(e.type==='chest'){ctx.fillStyle=e.opened?'#815a31':'#a87942';ctx.fillRect(cx-10,cy-5,20,13);ctx.fillStyle='#d1a85d';ctx.fillRect(cx-10,cy-8,20,6);ctx.fillStyle='#e4c57c';ctx.fillRect(cx-2,cy-3,4,5)
 }else if(e.type==='sign'){ctx.fillStyle='#614a32';ctx.fillRect(cx-2,cy-7,4,17);ctx.fillStyle='#bd9a60';ctx.fillRect(cx-10,cy-12,20,9);ctx.fillStyle='#806a44';ctx.fillRect(cx-7,cy-9,14,1)}
 if(e===selected||dist(state,e)<2.4){ctx.font='10px DM Sans';ctx.textAlign='center';ctx.textBaseline='bottom';ctx.lineWidth=3;ctx.strokeStyle='#15211ee8';ctx.strokeText(e.name,cx,cy-23);ctx.fillStyle=e===selected?'#f0d99c':'#f1eddb';ctx.fillText(e.name,cx,cy-23)}ctx.restore();}
function drawPlayer(){const p=screen(state.x,state.y),cx=p.x+TW/2,cy=p.y+TH/2,step=(keys.w||keys.a||keys.s||keys.d||moveGoal)?Math.sin(time*13)*2:0;ctx.fillStyle='#182a277a';ctx.beginPath();ctx.ellipse(cx,cy+9,12,5,0,0,7);ctx.fill();ctx.fillStyle='#c9a36e';ctx.beginPath();ctx.arc(cx,cy-8+step,6,0,7);ctx.fill();ctx.fillStyle='#497e75';ctx.beginPath();ctx.roundRect(cx-8,cy-3+step,16,15,5);ctx.fill();ctx.fillStyle='#d8d0b1';ctx.fillRect(cx-7,cy+10,5,8);ctx.fillRect(cx+2,cy+10,5,8);ctx.fillStyle='#27342e';ctx.fillRect(cx-3,cy-9+step,1.5,2);ctx.fillRect(cx+2,cy-9+step,1.5,2);if(state.equipped){ctx.strokeStyle='#dfc17c';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(cx+8,cy+3);ctx.lineTo(cx+14,cy-4);ctx.stroke()}}
function drawMini(){mctx.clearRect(0,0,260,200);for(let y=0;y<WH;y++)for(let x=0;x<WW;x++){let t=terrain(x,y);mctx.fillStyle=t==='water'?'#477d78':t==='path'?'#aa9368':t==='flower'?'#708757':'#52734d';mctx.fillRect(x*260/WW,y*200/WH,260/WW+1,200/WH+1)}for(const e of entities){mctx.fillStyle=e.type==='enemy'?'#e68c67':e.type==='ore'?'#e4b56d':e.type==='npc'?'#f4e3a8':'#aec88a';mctx.fillRect(e.x*260/WW-1,e.y*200/WH-1,3,3)}mctx.fillStyle='#fff1bd';mctx.beginPath();mctx.arc(state.x*260/WW,state.y*200/WH,3,0,7);mctx.fill();mctx.strokeStyle='#ffffff88';mctx.strokeRect(camera.x/WW/TW*260,camera.y/WH/TH*200,W/(WW*TW)*260,H/(WH*TH)*200)}

