function drawMini(){mctx.clearRect(0,0,260,200);for(let y=0;y<WH;y++)for(let x=0;x<WW;x++){let t=terrain(x,y);mctx.fillStyle=t==='water'?'#477d78':t==='path'?'#aa9368':t==='flower'?'#708757':'#52734d';mctx.fillRect(x*260/WW,y*200/WH,260/WW+1,200/WH+1)}for(const e of entities){mctx.fillStyle=e.type==='enemy'?'#e68c67':e.type==='ore'?'#e4b56d':e.type==='npc'?'#f4e3a8':'#aec88a';mctx.fillRect(e.x*260/WW-1,e.y*200/WH-1,3,3)}mctx.fillStyle='#fff1bd';mctx.beginPath();mctx.arc(state.x*260/WW,state.y*200/WH,3,0,7);mctx.fill();mctx.strokeStyle='#ffffff88';mctx.strokeRect(camera.x/WW/TW*260,camera.y/WH/TH*200,W/(WW*TW)*260,H/(WH*TH)*200)}
function nearest(){return entities.filter(e=>e.amount!==0&&!(e.type==='enemy'&&e.hp<=0)).sort((a,b)=>dist(state,a)-dist(state,b))[0]}
function panelTarget(e){selected=e||null;const name=document.querySelector('#targetName'),desc=document.querySelector('#targetDesc'),range=document.querySelector('#rangeBadge'),primary=document.querySelector('#primaryAction');if(!e){name.textContent='The meadow awaits';desc.textContent='Walk up to a tree, ore vein, creature, or villager to interact.';range.textContent='—';primary.textContent='Explore';return}name.textContent=e.name;desc.textContent=e.desc||({tree:'Gather sturdy wildwood for crafting and camp repairs.',ore:'Mine copper ore. A few good strikes should loosen it.',enemy:`Level ${e.level} · ${e.hp}/${e.maxHp} vitality · It looks ready to fight.`,herb:'A bright, restorative sunleaf. Useful for simple tonics.',camp:'Warmth, rest, and a place to craft equipment.',chest:'An old traveler's cache, tucked under the ferns.',sign:'Weathered trail marker.'}[e.type]||'A friendly face in the meadow.');range.textContent=dist(state,e)<1.9?'IN REACH':`${dist(state,e).toFixed(1)}m`;primary.textContent=({tree:'Gather',ore:'Mine',enemy:'Attack',herb:'Gather',npc:'Speak',camp:'Craft',chest:e.opened?'Empty':'Open',sign:'Read'}[e.type]||'Interact')}
let combatTimer=0,enemyTimer=0,autoAction=null;
function beginAction(e){if(!e)return;selected=e;moveGoal=null;clickTarget=e;if(dist(state,e)>1.65){moveGoal={x:e.x,y:e.y};autoAction=e;message(`Heading to ${e.name}…`)}else interact(e)}
function interact(e){if(!e)return;selected=e;autoAction=null;moveGoal=null;
 if(e.type==='tree'||e.type==='ore'||e.type==='herb'){if(e.amount<=0){message('Nothing left to gather here.');return}e.amount--;if(e.type==='tree'){addItem('wood');gainSkill('forage',12);message('You gather a wildwood log.')}else if(e.type==='ore'){addItem('ore');gainSkill('mining',14);message('You mine a piece of copper ore.')}else{addItem('herb');gainSkill('forage',10);message('You pick a sunleaf herb.')};if(e.amount===0){message(`${e.name} is depleted; it will return soon.`);setTimeout(()=>{e.amount=e.type==='tree'?3:e.type==='ore'?4:1;message(`${e.name} has regrown.`);draw()},14000)}save();panelTarget(e)
 }else if(e.type==='npc'){if(!state.quest.talked){state.quest.talked=true;message('Elowen: “The ward-stone needs wildwood and copper. Will you help?”');openModal('A Meadow’s Promise','“The old ward-stone has lost its glow,” says Warden Elowen. “Bring me three wildwood logs and two copper ore. The meadow will be safer for everyone.” Your gathering task is now marked in the journal.');updateUI()}else if(!state.quest.done&&itemCount('wood')>=3&&itemCount('ore')>=2){state.items.wood-=3;state.items.ore-=2;state.quest.done=true;state.coins+=45;addItem('potion');gainXp(50);message('Quest complete! You receive 45 crowns and a tonic.');openModal('The ward shines again','Elowen places your offerings beside the stone. Golden light spills through the meadow. “You have a home here, wayfarer.” You earned 45 crowns, a tonic, and 50 renown.');updateUI();save()}else if(state.quest.done){message('Elowen: “The meadow is brighter for your kindness. Take this, with my thanks.”');state.coins+=2;updateUI();save()}else{message(`Elowen: “We still need ${Math.max(0,3-itemCount('wood'))} logs and ${Math.max(0,2-itemCount('ore'))} ore.”`)}
 }else if(e.type==='enemy'){if(e.hp<=0)return;selected=e;combatTimer=0;message(`You engage the ${e.name}!`)}
 else if(e.type==='camp'){openModal('Wayfarer’s campfire',`The fire crackles softly.\n\n${itemCount('ore')>=3&&itemCount('wood')>=1?'You have enough materials to forge a copper blade. Tap Craft below.':'To forge a copper blade, gather 3 copper ore and 1 wildwood log.'}`);document.querySelector('#primaryAction').textContent='Forge blade'}
 else if(e.type==='chest'){if(e.opened){message('The satchel is empty.')}else{e.opened=true;state.coins+=18;addItem('potion');message('Inside: 18 crowns and a sun tonic!');updateUI();save()}}
 else if(e.type==='sign'){openModal('Meadow trail sign','MOSSlight Meadow lies at the heart of the Greenward. The streams run north; copper can be found among the eastern rocks. Beware the slimes beyond the lantern path.')}
}
function attack(e){if(!e||e.type!=='enemy'||e.hp<=0)return;const power=3+(state.equipped?4:0)+Math.floor((state.levels.combat-1)*.7);e.hp-=power;message(`You strike for ${power} damage.`);if(e.hp<=0){e.hp=0;state.coins+=e.level*3;gainXp(e.level*18);gainSkill('combat',18);message(`${e.name} dissolves into a puff of meadow mist. +${e.level*3} crowns`);setTimeout(()=>{e.hp=e.maxHp;e.x=Math.min(WW-2,Math.max(2,e.x+(rand(e.x,time)-.5)*5));e.y=Math.min(WH-2,Math.max(2,e.y+(rand(e.y,time)-.5)*5));draw()},16000);selected=null;autoAction=null;panelTarget(null);save()}else{combatTimer=.42}updateUI()}
function useItem(k){if(itemCount(k)<=0)return;if(k==='potion'){if(state.hp>=state.maxHp){message('Your vitality is already full.');return}state.items.potion--;state.hp=Math.min(state.maxHp,state.hp+14);message('You drink a sun tonic and recover vitality.')}else if(k==='blade'){state.equipped=!state.equipped;message(state.equipped?'Copper blade equipped.':'Copper blade unequipped.')}else{message(`${k==='wood'?'Wildwood log':k==='ore'?'Copper ore':'Sunleaf herb'} — gathered for crafting.`)}updateUI();save()}
function craft(){if(itemCount('ore')<3||itemCount('wood')<1){message('Need 3 copper ore and 1 wildwood log to forge a blade.');return}state.items.ore-=3;state.items.wood--;state.items.blade=1;state.equipped=true;gainSkill('craft',35);message('Forged a copper blade! Your attacks hit harder.');updateUI();save();document.querySelector('#modal').classList.remove('show')}
function rest(){if(state.hp===state.maxHp){message('You feel well rested already.');return}state.hp=Math.min(state.maxHp,state.hp+8);message('You catch your breath and recover 8 vitality.');updateUI();save()}
function openModal(title,text){document.querySelector('#modalTitle').textContent=title;document.querySelector('#modalText').textContent=text;document.querySelector('#modal').classList.add('show')}

