document.querySelector('#modal').addEventListener('click',ev=>{if(ev.target.id==='modal')ev.currentTarget.classList.remove('show')});setInterval(save,10000);window.addEventListener('beforeunload',save);panelTarget(null);message('The morning mist lifts over Mosslight Meadow.');requestAnimationFrame(tick);
})();
</script>
